{"owner": "pt251219-png", "repo": "pt251219-png.github.io", "path": "kịch-bản-to-ảnh/backend/app.py", "message": "Tạo Flask backend chính", "content": "from flask import Flask, request, jsonify
from flask_cors import CORS
import os
from dotenv import load_dotenv
import requests
from PIL import Image, ImageDraw, ImageFont
import io
import base64

load_dotenv()

app = Flask(__name__)
CORS(app)

# Cấu hình API keys
OPENROUTER_API_KEY = os.getenv('OPENROUTER_API_KEY', '')
REPLICATE_API_TOKEN = os.getenv('REPLICATE_API_TOKEN', '')

# Các model miễn phí từ OpenRouter
AVAILABLE_MODELS = {
    'openchat': 'openchat/openchat-7b:free',
    'mistral': 'mistralai/mistral-7b:free',
    'llama2': 'meta-llama/llama-2-7b:free'
}

@app.route('/api/suc-khoe', methods=['GET'])
def suc_khoe():
    """Kiểm tra trạng thái ứng dụng"""
    return jsonify({'trạng_thái': 'hoạt động', 'phiên_bản': '1.0.0'})

@app.route('/api/tạo-prompt', methods=['POST'])
def tao_prompt():
    """Tạo prompt cho AI từ kịch bản"""
    try:
        dữ_liệu = request.json
        kịch_bản = dữ_liệu.get('kịch_bản', '')

        if not kịch_bản:
            return jsonify({'lỗi': 'Vui lòng cung cấp kịch bản'}), 400

        # Tạo prompt để mô tả nhân vật cổ truyền Trung Quốc
        prompt = f"""Bạn là một nghệ sĩ minh họa chuyên vẽ nhân vật cổ truyền Trung Quốc.

Kịch bản: {kịch_bản}

Hãy mô tả chi tiết những gì cần vẽ:
1. Nhân vật chính (tên, ngoại hình, phục trang cổ truyền)
2. Cảnh nền (nơi diễn ra, thời đại)
3. Biểu cảm khuôn mặt
4. Tư thế cơ thể
5. Chi tiết trang trí, vũ khí, phụ kiện

Mô tả phải chi tiết và dễ vẽ bằng prompt image generation."""

        return jsonify({'prompt': prompt})
    except Exception as e:
        return jsonify({'lỗi': str(e)}), 500

@app.route('/api/tạo-ảnh', methods=['POST'])
def tao_anh():
    """Tạo ảnh từ kịch bản sử dụng API miễn phí"""
    try:
        dữ_liệu = request.json
        mô_tả = dữ_liệu.get('mô_tả', '')

        if not mô_tả:
            return jsonify({'lỗi': 'Vui lòng cung cấp mô tả ảnh'}), 400

        # Tạo prompt cho Flux/Stable Diffusion
        prompt_tối_ưu = f"""Minh họa nhân vật cổ truyền Trung Quốc, phong cách 2D anime, chất lượng cao:
{mô_tả}

Yêu cầu:
- Phong cách tranh vẽ tay cổ truyền Trung Quốc
- Màu sắc tươi sáng, sống động
- Chi tiết phục trang cổ truyền chính xác
- Khuôn hình toàn thân"""

        # Sử dụng Replicate API (miễn phí)
        if REPLICATE_API_TOKEN:
            return tao_anh_replicate(prompt_tối_ưu)
        else:
            # Fallback: Tạo ảnh giả để demo
            return tao_anh_demo(prompt_tối_ưu)

    except Exception as e:
        return jsonify({'lỗi': str(e)}), 500

def tao_anh_replicate(prompt):
    """Tạo ảnh sử dụng Replicate (Flux model miễn phí)"""
    try:
        import httpx

        client = httpx.Client()
        response = client.post(
            "https://api.replicate.com/v1/predictions",
            headers={
                "Authorization": f"Token {REPLICATE_API_TOKEN}",
                "Content-Type": "application/json",
            },
            json={
                "version": "e04e9dce70f37b502c7bef278a2717fa47d02210577ee47928658bada26436ce",  # Flux model
                "input": {
                    "prompt": prompt,
                    "num_outputs": 1,
                    "aspect_ratio": "1:1",
                    "output_format": "jpg",
                    "output_quality": 80,
                }
            }
        )

        if response.status_code == 201:
            kết_quả = response.json()
            return jsonify({
                'thành_công': True,
                'ảnh_url': kết_quả['output'][0] if kết_quả.get('output') else None,
                'request_id': kết_quả.get('id')
            })
        else:
            return jsonify({'lỗi': 'Lỗi API Replicate'}), 500

    except Exception as e:
        return jsonify({'lỗi': str(e)}), 500

def tao_anh_demo(prompt):
    """Tạo ảnh demo (giả) để test"""
    try:
        # Tạo ảnh 512x512 với nền gradient
        ảnh = Image.new('RGB', (512, 512), color=(240, 200, 150))
        draw = ImageDraw.Draw(ảnh)

        # Vẽ một số hình để demo
        draw.ellipse([150, 100, 350, 300], fill=(200, 100, 50), outline=(139, 69, 19))  # Đầu
        draw.rectangle([200, 320, 300, 480], fill=(255, 200, 100), outline=(139, 69, 19))  # Thân
        draw.rectangle([180, 320, 220, 450], fill=(255, 200, 100))  # Tay trái
        draw.rectangle([280, 320, 320, 450], fill=(255, 200, 100))  # Tay phải

        # Thêm text
        try:
            # Thử load font Unicode
            font = ImageFont.load_default()
        except:
            font = ImageFont.load_default()

        draw.text((50, 20), "Anh 2D Co Truyen Trung Quoc", fill=(0, 0, 0), font=font)

        # Chuyển đổi sang base64
        buffer = io.BytesIO()
        ảnh.save(buffer, format='JPEG')
        ảnh_base64 = base64.b64encode(buffer.getvalue()).decode()

        return jsonify({
            'thành_công': True,
            'ảnh_base64': ảnh_base64,
            'ghi_chú': 'Đây là ảnh demo. Vui lòng cấu hình REPLICATE_API_TOKEN để tạo ảnh thực tế'
        })
    except Exception as e:
        return jsonify({'lỗi': str(e)}), 500

@app.route('/api/phân-tích-kịch-bản', methods=['POST'])
def phân_tích_kịch_bản():
    """Phân tích kịch bản sử dụng OpenRouter API (miễn phí)"""
    try:
        dữ_liệu = request.json
        kịch_bản = dữ_liệu.get('kịch_bản', '')
        model = dữ_liệu.get('model', 'openchat')

        if not kịch_bản:
            return jsonify({'lỗi': 'Vui lòng cung cấp kịch bản'}), 400

        if not OPENROUTER_API_KEY:
            return jsonify({'lỗi': 'Vui lòng cấu hình OPENROUTER_API_KEY trong .env'}), 500

        model_id = AVAILABLE_MODELS.get(model, AVAILABLE_MODELS['openchat'])

        prompt = f"""Phân tích kịch bản này và tạo mô tả nhân vật cổ truyền Trung Quốc:

Kịch bản: {kịch_bản}

Trả lời với JSON chứa:
{{
  "tên_nhân_vật": "...",
  "độ_tuổi": "...",
  "phục_trang": "...",
  "vũ_khí": "...",
  "đặc_điểm_ngoại_hình": "...",
  "tâm_trạng": "...",
  "bối_cảnh": "..."
}}"""

        response = requests.post(
            "https://openrouter.io/api/v1/chat/completions",
            headers={
                "Authorization": f"Bearer {OPENROUTER_API_KEY}",
                "HTTP-Referer": "https://pt251219-png.github.io",
                "Content-Type": "application/json"
            },
            json={
                "model": model_id,
                "messages": [
                    {"role": "user", "content": prompt}
                ],
                "temperature": 0.7,
                "max_tokens": 1000
            }
        )

        if response.status_code == 200:
            kết_quả = response.json()
            nội_dung = kết_quả['choices'][0]['message']['content']
            return jsonify({
                'thành_công': True,
                'phân_tích': nội_dung
            })
        else:
            return jsonify({'lỗi': f'Lỗi API: {response.status_code}'}), 500

    except Exception as e:
        return jsonify({'lỗi': str(e)}), 500

@app.route('/api/models', methods=['GET'])
def danh_sách_models():
    """Danh sách các model có sẵn"""
    return jsonify({
        'models': list(AVAILABLE_MODELS.keys()),
        'ghi_chú': 'Tất cả là các model miễn phí từ OpenRouter'
    })

if __name__ == '__main__':
    app.run(debug=True, port=5000)
"}

