}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.6;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* Header */
.header {
  background: linear-gradient(135deg, var(--secondary-color), #c41e3a);
  color: white;
  padding: 2rem 0;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

.header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-size: 2rem;
  font-weight: bold;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
}

.nav {
  display: flex;
  gap: 1rem;
}

.nav-btn {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: 2px solid transparent;
  padding: 0.5rem 1.5rem;
  border-radius: 20px;
  cursor: pointer;
  font-size: 1rem;
  transition: all 0.3s ease;
}

.nav-btn:hover {
  background: rgba(255, 255, 255, 0.3);
  border-color: var(--primary-color);
}

.nav-btn.active {
  background: var(--primary-color);
  color: var(--secondary-color);
  border-color: var(--primary-color);
}

/* Main */
.main {
  flex: 1;
  padding: 2rem 0;
}

/* Footer */
.footer {
  background: var(--secondary-color);
  color: white;
  text-align: center;
  padding: 2rem;
  margin-top: 2rem;
  border-top: 3px solid var(--primary-color);
}

/* Trang Chủ */
.trang-chủ {
  padding: 2rem 0;
}

.hero {
  background: linear-gradient(135deg, var(--secondary-color), #c41e3a);
  color: white;
  padding: 4rem 2rem;
  text-align: center;
  border-radius: 10px;
  margin-bottom: 3rem;
}

.hero-content h2 {
  font-size: 2.5rem;
  margin-bottom: 1rem;
  text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
}

.hero-content p {
  font-size: 1.2rem;
  margin-bottom: 2rem;
  opacity: 0.95;
}

/* Nút */
.btn-primary {
  background: var(--primary-color);
  color: var(--secondary-color);
  border: none;
  padding: 0.8rem 2rem;
  border-radius: 5px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  transition: all 0.3s ease;
}

.btn-primary:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 6px 12px rgba(212, 175, 55, 0.3);
}

.btn-primary:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.btn-secondary {
  background: white;
  color: var(--secondary-color);
  border: 2px solid var(--secondary-color);
  padding: 0.6rem 1.5rem;
  border-radius: 5px;
  font-size: 0.9rem;
  cursor: pointer;
  transition: all 0.3s ease;
}

.btn-secondary:hover {
  background: var(--secondary-color);
  color: white;
}

/* Features */
.features, .cách-dùng, .api-info {
  margin-bottom: 3rem;
}

.features h2, .cách-dùng h2, .api-info h2 {
  text-align: center;
  font-size: 2rem;
  color: var(--secondary-color);
  margin-bottom: 2rem;
  text-decoration: underline;
  text-decoration-color: var(--primary-color);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
}

.feature-card {
  background: white;
  padding: 2rem;
  border-radius: 10px;
  text-align: center;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  transition: transform 0.3s ease;
}

.feature-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.15);
}

.feature-icon {
  font-size: 3rem;
  margin-bottom: 1rem;
}

.feature-card h3 {
  color: var(--secondary-color);
  margin-bottom: 0.5rem;
}

/* Steps */
.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-bottom: 2rem;
}

.step {
  background: white;
  padding: 2rem;
  border-radius: 10px;
  text-align: center;
  border-left: 5px solid var(--primary-color);
}

.step-number {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 50px;
  height: 50px;
  background: var(--primary-color);
  color: var(--secondary-color);
  border-radius: 50%;
  font-size: 1.5rem;
  font-weight: bold;
  margin: 0 auto 1rem;
}

.step h3 {
  color: var(--secondary-color);
  margin-bottom: 0.5rem;
}

/* API Cards */
.api-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
}

.api-card {
  background: white;
  padding: 2rem;
  border-radius: 10px;
  border: 2px solid var(--primary-color);
  text-align: center;
}

.api-card h3 {
  color: var(--secondary-color);
  margin-bottom: 1rem;
}

.api-card a {
  display: inline-block;
  margin-top: 1rem;
  color: var(--secondary-color);
  text-decoration: none;
  font-weight: bold;
  transition: all 0.3s ease;
}

.api-card a:hover {
  color: var(--primary-color);
}

/* Responsive */
@media (max-width: 768px) {
  .header .container {
    flex-direction: column;
    gap: 1rem;
  }

  .logo {
    font-size: 1.5rem;
  }

  .hero-content h2 {
    font-size: 1.5rem;
  }

  .features-grid, .steps, .api-cards {
    grid-template-columns: 1fr;
  }

  .nav {
    width: 100%;
    justify-content: center;
  }
}
"}

