import { Menu, X } from 'lucide-react'
import TextToSpeech from './pages/TextToSpeech'
import TextToVideo from './pages/TextToVideo'
import ImageToVideo from './pages/ImageToVideo'
import ScriptAnalyzer from './pages/ScriptAnalyzer'
import './styles/App.css'

function App() {
  const [activeTab, setActiveTab] = useState('tts')
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false)

  const tabs = [
    { id: 'tts', label: '🎤 Text → Giọng Nói', component: TextToSpeech },
    { id: 'text-video', label: '🎥 Text → Video', component: TextToVideo },
    { id: 'image-video', label: '🖼️ Ảnh → Video', component: ImageToVideo },
    { id: 'script', label: '🤖 Phân Tích Kịch Bản', component: ScriptAnalyzer },
  ]

  const ActiveComponent = tabs.find(t => t.id === activeTab)?.component

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-900 via-indigo-900 to-blue-900">
      {/* Header */}
      <header className="bg-black/40 backdrop-blur-md border-b border-purple-500/30 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="text-2xl">🎬</div>
            <div>
              <h1 className="text-2xl font-bold text-white">Chuyển Đổi Media</h1>
              <p className="text-xs text-purple-200">Bản Miễn Phí v1.0</p>
            </div>
          </div>

          {/* Mobile Menu Button */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="md:hidden text-white p-2"
          >
            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </header>

      {/* Navigation */}
      <nav className={`${mobileMenuOpen ? 'block' : 'hidden'} md:block bg-black/20 backdrop-blur-sm border-b border-purple-500/20`}>
        <div className="max-w-7xl mx-auto px-4 py-3">
          <div className="flex flex-col md:flex-row gap-2">
            {tabs.map(tab => (
              <button
                key={tab.id}
                onClick={() => {
                  setActiveTab(tab.id)
                  setMobileMenuOpen(false)
                }}
                className={`px-4 py-2 rounded-lg font-semibold transition-all ${
                  activeTab === tab.id
                    ? 'bg-gradient-to-r from-purple-500 to-pink-500 text-white shadow-lg'
                    : 'text-gray-300 hover:bg-purple-500/20 hover:text-white'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 py-8">
        <div className="bg-white/5 backdrop-blur-md rounded-2xl border border-purple-500/20 p-6 md:p-8 shadow-2xl">
          {ActiveComponent && <ActiveComponent />}
        </div>
      </main>

      {/* Footer */}
      <footer className="bg-black/40 backdrop-blur-md border-t border-purple-500/30 mt-12 py-6">
        <div className="max-w-7xl mx-auto px-4 text-center text-gray-400 text-sm">
          <p>Ứng dụng chuyển đổi media AI-powered | Bản miễn phí</p>
          <p className="mt-2">© 2024 Media Converter | Được tạo bởi pt251219-png</p>
        </div>
      </footer>
    </div>
  )
}

export default App
