{"branch": "feature/media-converter-v1", "content": "import { useState } from 'react'
import { Loader, Wand2, Download } from 'lucide-react'

export default function ScriptAnalyzer() {
  const [script, setScript] = useState('')
  const [style, setStyle] = useState('anime')
  const [isLoading, setIsLoading] = useState(false)
  const [generatedImages, setGeneratedImages] = useState([])

  const styles = [
    { id: 'anime', label: '🎨 Anime Nhật Bản', desc: 'Phong cách anime 2D' },
    { id: 'chinese', label: '🏯 Cổ Trang Trung Quốc', desc: 'Phong cách cổ trang Trung Quốc' },
    { id: 'watercolor', label: '🎭 Màu Nước Tây Phương', desc: 'Phong cách màu nước tây phương' },
    { id: 'manga', label: '📖 Manga Truyên Tranh', desc: 'Phong cách truyên tranh Manga' },
  ]

  const handleAnalyzeScript = async () => {
    if (!script.trim()) {
      alert('Vui lòng nhập kịch bản!')
      return
    }

    setIsLoading(true)
    try {
      // Giả lập gọi API OpenRouter
      const response = await fetch('https://openrouter.ai/api/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${import.meta.env.VITE_OPENROUTER_API_KEY || 'demo-key'}`
        },
        body: JSON.stringify({
          model: 'mistral/mistral-7b-instruct',
          messages: [{
            role: 'user',
            content: `Phân tích kịch bản này và tạo mô tả chi tiết cho ${styles.find(s => s.id === style)?.label}:\n\n${script}`
          }]
        })
      })

      if (response.ok) {
        const data = await response.json()
        alert('Kịch bản đã được phân tích!\n\nMô tả: ' + data.choices[0].message.content)
      } else {
        alert('Bản miễn phí cần cấu hình OpenRouter API Key. Xem tài liệu để lấy key miễn phí!')
      }
    } catch (error) {
      console.error('Lỗi:', error)
      alert('Không thể phân tích kịch bản. Đảm bảo API Key đúng!')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="max-w-2xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-6">🤖 Phân Tích Kịch Bản & Vẽ Hình</h2>

      {/* Script Input */}
      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Nhập Kịch Bản</label>
        <textarea
          value={script}
          onChange={(e) => setScript(e.target.value)}
          placeholder="Nhập kịch bản hoặc tình huống bạn muốn AI vẽ thành hình ảnh..."
          className="w-full h-40 px-4 py-3 rounded-lg bg-black/30 border border-purple-500/30 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50"
        />
        <p className="text-gray-400 text-sm mt-2">{script.length} ký tự</p>
      </div>

      {/* Style Selection */}
      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Lựa Chọn Phong Cách</label>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {styles.map(st => (
            <button
              key={st.id}
              onClick={() => setStyle(st.id)}
              className={`p-4 rounded-lg border-2 transition ${
                style === st.id
                  ? 'border-purple-500 bg-purple-500/20'
                  : 'border-purple-500/30 hover:border-purple-500/60 hover:bg-purple-500/10'
              }`}
            >
              <div className="text-white font-semibold">{st.label}</div>
              <div className="text-gray-400 text-sm">{st.desc}</div>
            </button>
          ))}
        </div>
      </div>

      {/* Examples */}
      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">📝 Ví Dụ Kịch Bản</label>
        <div className="space-y-2">
          <button
            onClick={() => setScript('Một cô gái mặc áo cổ trang Trung Quốc đứng trên tòa lâu đài cao, nhìn ra phía dưới thung lũng. Mặt trời lặn tạo ra ánh sáng vàng rực rỡ. Trên tay cô ấy là một quyển sách cổ xưa.')}
            className="w-full text-left px-4 py-2 bg-purple-500/10 border border-purple-500/30 rounded hover:bg-purple-500/20 text-gray-300 text-sm"
          >
            ✨ Ví dụ 1: Cô gái trên lâu đài
          </button>
          <button
            onClick={() => setScript('Hai chiến binh cổ trang Trung Quốc đối diện nhau trong một trận chiến epicc. Họ cầm kiếm sáng bạc, mặt trời mọc phía sau. Lá cây rơi xuống từ trên trời.')}
            className="w-full text-left px-4 py-2 bg-purple-500/10 border border-purple-500/30 rounded hover:bg-purple-500/20 text-gray-300 text-sm"
          >
            ⚔️ Ví dụ 2: Trận chiến anh hùng
          </button>
        </div>
      </div>

      {/* Buttons */}
      <div className="flex gap-4 flex-col md:flex-row">
        <button
