import { Play, Pause, Volume2, RotateCcw } from 'lucide-react'
import Button from '../components/Button'
import InputField from '../components/InputField'
import InfoBox from '../components/InfoBox'
import LoadingSpinner from '../components/LoadingSpinner'
import useAudio from '../hooks/useAudio'

const LANGUAGES = [
  { code: 'vi-VN', label: '🇻🇳 Tiếng Việt' },
  { code: 'en-US', label: '🇺🇸 Tiếng Anh (Mỹ)' },
  { code: 'en-GB', label: '🇬🇧 Tiếng Anh (UK)' },
  { code: 'zh-CN', label: '🇨🇳 Tiếng Trung (Giản)' },
  { code: 'zh-TW', label: '🇨🇳 Tiếng Trung (Phồn)' },
  { code: 'ja-JP', label: '🇯🇵 Tiếng Nhật' },
  { code: 'ko-KR', label: '🇰🇷 Tiếng Hàn' },
  { code: 'es-ES', label: '🇪🇸 Tiếng Tây Ban Nha' },
  { code: 'fr-FR', label: '🇫🇷 Tiếng Pháp' },
  { code: 'de-DE', label: '🇩🇪 Tiếng Đức' },
]

export default function TextToSpeech() {
  const [text, setText] = useState('')
  const [language, setLanguage] = useState('vi-VN')
  const [pitch, setPitch] = useState(1)
  const [speed, setSpeed] = useState(1)
  const { isPlaying, speak, stop } = useAudio()

  const handleSpeak = () => {
    if (!text.trim()) {
      alert('Vui lòng nhập văn bản!')
      return
    }
    speak(text, language, speed, pitch)
  }

  const handleClear = () => {
    setText('')
    stop()
  }

  return (
    <div className="max-w-3xl mx-auto">
      <div className="mb-8">
        <h2 className="text-4xl font-bold text-white mb-2">🎤 Chuyển Text Thành Giọng Nói</h2>
        <p className="text-gray-300">Nhập văn bản và nghe AI đọc lại với các giọng khác nhau</p>
      </div>

      {/* Text Input */}
      <div className="mb-6">
        <label className="block text-white font-semibold mb-3">Nhập Văn Bản</label>
        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Nhập văn bản mà bạn muốn chuyển thành giọng nói..."
          className="w-full h-40 px-4 py-3 rounded-lg bg-black/30 border border-purple-500/30 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50 resize-none"
