            <span className="text-gray-400 text-sm">0.5x</span>
            <input
              type="range"
              min="0.5"
              max="2"
              step="0.1"
              value={speed}
              onChange={(e) => setSpeed(parseFloat(e.target.value))}
              className="flex-grow h-2 bg-purple-500/30 rounded-lg appearance-none cursor-pointer accent-purple-500"
            />
            <span className="text-gray-400 text-sm">2x</span>
          </div>
        </div>
      </div>

      {/* Pitch Control */}
      <div className="mb-8">
        <label className="block text-white font-semibold mb-3">
          Cao Độ Giọng: <span className="text-purple-400">{pitch.toFixed(1)}</span>
        </label>
        <div className="flex items-center gap-3">
          <span className="text-gray-400 text-sm">Thấp</span>
          <input
            type="range"
            min="0.5"
            max="2"
            step="0.1"
            value={pitch}
            onChange={(e) => setPitch(parseFloat(e.target.value))}
