import { Wand2, Copy, Download } from 'lucide-react'
import Button from '../components/Button'
import InfoBox from '../components/InfoBox'
import LoadingSpinner from '../components/LoadingSpinner'
import { analyzeScript } from '../services/openrouter'

const STYLES = [
  { id: 'anime', label: '🎨 Anime Nhật Bản', desc: 'Phong cách anime 2D' },
  { id: 'chinese', label: '🏯 Cổ Trang Trung Quốc', desc: 'Phong cách cổ trang Trung Quốc' },
  { id: 'watercolor', label: '🎭 Màu Nước Tây Phương', desc: 'Phong cách màu nước' },
  { id: 'manga', label: '📖 Manga', desc: 'Phong cách truyên tranh Manga' },
]

const EXAMPLES = [
  {
    title: '✨ Ví dụ 1: Cô gái trên lâu đài',
    text: 'Một cô gái mặc áo cổ trang Trung Quốc đứng trên tòa lâu đài cao, nhìn ra phía dưới thung lũng. Mặt trời lặn tạo ra ánh sáng vàng rực rỡ. Trên tay cô ấy là một quyển sách cổ xưa.'
  },
  {
    title: '⚔️ Ví dụ 2: Trận chiến anh hùng',
    text: 'Hai chiến binh cổ trang Trung Quốc đối diện nhau trong một trận chiến epic. Họ cầm kiếm sáng bạc, mặt trời mọc phía sau. Lá cây rơi xuống từ trên trời.'
  },
  {
    title: '🌸 Ví dụ 3: Khoảnh khắc lãng mạn',
    text: 'Hai vị tiên nữ mặc áo ước dài bay lơ lửng giữa những đám mây trắng. Hoa anh đào rơi quanh họ, ánh sáng mặt trời làm cho mọi thứ bóng loáng vàng.'
  }
]

export default function ScriptAnalyzer() {
  const [script, setScript] = useState('')
  const [style, setStyle] = useState('chinese')
  const [isLoading, setIsLoading] = useState(false)
  const [result, setResult] = useState('')
  const [error, setError] = useState('')

  const handleAnalyze = async () => {
    if (!script.trim()) {
      setError('Vui lòng nhập kịch bản!')
      return
    }

    setIsLoading(true)
    setError('')
    setResult('')

    try {
      const analysis = await analyzeScript(script, style)
      setResult(analysis)
    } catch (err) {
      setError(err.message || 'Không thể phân tích. Kiểm tra API Key!')
      console.error(err)
    } finally {
      setIsLoading(false)
    }
  }

  const handleCopy = () => {
    navigator.clipboard.writeText(result)
    alert('Đã sao chép vào clipboard!')
  }

  return (
    <div className="max-w-4xl mx-auto">
      <div className="mb-8">
        <h2 className="text-4xl font-bold text-white mb-2">🤖 Phân Tích Kịch Bản & Vẽ Hình</h2>
        <p className="text-gray-300">Nhập kịch bản và AI sẽ tạo mô tả chi tiết để vẽ thành hình ảnh 2D</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Script Input */}
          <div>
            <label className="block text-white font-semibold mb-3">Nhập Kịch Bản</label>
            <textarea
              value={script}
              onChange={(e) => setScript(e.target.value)}
              placeholder="Mô tả chi tiết kịch bản, nhân vật, cảnh canh..."
              className="w-full h-40 px-4 py-3 rounded-lg bg-black/30 border border-purple-500/30 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50 resize-none"
            />
            <p className="text-gray-400 text-sm mt-2">{script.length} ký tự</p>
          </div>

          {/* Style Selection */}
          <div>
            <label className="block text-white font-semibold mb-3">Phong Cách Vẽ</label>
            <div className="grid grid-cols-2 gap-3">
              {STYLES.map(st => (
                <button
                  key={st.id}
                  onClick={() => setStyle(st.id)}
                  className={`p-3 rounded-lg border-2 transition text-left ${
                    style === st.id
                      ? 'border-purple-500 bg-purple-500/20'
                      : 'border-purple-500/30 hover:border-purple-500/60 hover:bg-purple-500/10'
                  }`}
                >
                  <div className="text-white font-semibold text-sm">{st.label}</div>
                  <div className="text-gray-400 text-xs">{st.desc}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Analyze Button */}
          <Button
            variant="primary"
            size="lg"
            disabled={!script.trim() || isLoading}
            onClick={handleAnalyze}
            icon={Wand2}
            className="w-full"
          >
            {isLoading ? 'Đang Phân Tích...' : 'Phân Tích & Tạo Mô Tả'}
          </Button>

          {/* Result */}
          {result && (
            <div>
              <div className="flex justify-between items-center mb-3">
                <label className="text-white font-semibold">Kết Quả Phân Tích</label>
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleCopy}
                  icon={Copy}
                >
                  Sao Chép
                </Button>
              </div>
              <div className="p-4 rounded-lg bg-black/30 border border-purple-500/30 text-gray-200 max-h-64 overflow-y-auto whitespace-pre-wrap text-sm leading-relaxed">
                {result}
              </div>
            </div>
          )}

          {error && (
            <InfoBox
              type="error"
              title="❌ Lỗi"
              message={error}
            />
          )}
        </div>

        {/* Sidebar - Examples */}
        <div>
          <label className="block text-white font-semibold mb-3">📝 Ví Dụ Kịch Bản</label>
          <div className="space-y-2">
            {EXAMPLES.map((example, idx) => (
              <button
                key={idx}
                onClick={() => setScript(example.text)}
                className="w-full text-left px-3 py-2 bg-purple-500/10 border border-purple-500/30 rounded hover:bg-purple-500/20 text-gray-300 hover:text-white text-sm transition"
              >
                {example.title}
              </button>
            ))}
          </div>

          {/* Info */}
          <div className="mt-6">
            <InfoBox
              type="info"
              title="💡 Tip"
            >
              <ul className="text-xs space-y-1 mt-2 list-disc ml-4">
                <li>Viết mô tả chi tiết</li>
                <li>Nêu rõ ngôn ngữ lập</li>
                <li>Cổ Trang TQ hay nhất</li>
                <li>Cần OpenRouter API</li>
              </ul>
            </InfoBox>
          </div>
        </div>
      </div>
    </div>
  )
}
