          onChange={(e) => setSpeed(parseFloat(e.target.value))}
          className="w-full h-2 bg-purple-500/30 rounded-lg appearance-none cursor-pointer accent-purple-500"
        />
      </div>

      <div className="flex gap-4 flex-col md:flex-row">
        <button
          onClick={handleSpeak}
          disabled={isLoading || !text.trim()}
          className="flex-1 bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-lg transition-all flex items-center justify-center gap-2"
        >
          {isLoading ? (
            <>
              <Loader size={20} className="animate-spin" />
              Đang Phát...
            </>
          ) : (
            <>
              <Play size={20} />
              Phát Âm Thanh
            </>
          )}
        </button>

        <button
          onClick={handleDownload}
          disabled={isLoading || !text.trim()}
          className="flex-1 bg-gradient-to-r from-green-500 to-emerald-500 hover:from-green-600 hover:to-emerald-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-lg transition-all flex items-center justify-center gap-2"
        >
          <Download size={20} />
          Tải Xuống MP3
        </button>
      </div>

      <div className="mt-8 p-4 bg-blue-500/10 border border-blue-500/30 rounded-lg">
        <p className="text-blue-200 text-sm">
          <strong>ℹ️ Lưu ý:</strong> Bản miễn phí sử dụng Web Speech API của trình duyệt. Để tải xuống MP3, bạn cần cấu hình Google Cloud TTS API.
        </p>
      </div>

      <audio ref={audioRef} />
    </div>
  )
}"},{"path":"media-converter/src/pages/TextToVideo.jsx","content":"import { useState } from 'react'
import { Loader, Play, Download } from 'lucide-react'

export default function TextToVideo() {
  const [title, setTitle] = useState('')
  const [text, setText] = useState('')
  const [background, setBackground] = useState('nature')
  const [musicOption, setMusicOption] = useState('none')
  const [isLoading, setIsLoading] = useState(false)
  const [videoUrl, setVideoUrl] = useState(null)

  const backgrounds = [
    { id: 'nature', label: 'Thiên Nhiên', color: 'bg-green-600' },
    { id: 'city', label: 'Thành Phố', color: 'bg-gray-600' },
    { id: 'night', label: 'Ban Đêm', color: 'bg-slate-900' },
    { id: 'ocean', label: 'Đại Dương', color: 'bg-blue-600' },
  ]

  const musicOptions = [
    { id: 'none', label: 'Không Có Nhạc' },
    { id: 'ambient', label: 'Ambient Nhẹ Nhàng' },
    { id: 'upbeat', label: 'Upbeat Năng Động' },
    { id: 'dramatic', label: 'Dramatic Kịch Tính' },
  ]

  const handleCreateVideo = async () => {
    if (!title.trim() || !text.trim()) {
      alert('Vui lòng nhập tiêu đề và nội dung!')
      return
    }

    setIsLoading(true)
    try {
      setTimeout(() => {
        alert('Trong bản miễn phí, tính năng tạo video yêu cầu cấu hình backend hoặc sử dụng API bên thứ 3! Xem tài liệu để tìm hiểu thêm.')
        setIsLoading(false)
      }, 2000)
    } catch (error) {
      console.error('Lỗi:', error)
      alert('Không thể tạo video!')
      setIsLoading(false)
    }
  }

  return (
    <div className="max-w-2xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-6">🎥 Chuyển Text Thành Video</h2>

      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Tiêu Đề Video</label>
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Nhập tiêu đề video..."
          className="w-full px-4 py-3 rounded-lg bg-black/30 border border-purple-500/30 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50"
        />
      </div>

      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Nội Dung</label>
        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Nhập nội dung cho video..."
          className="w-full h-32 px-4 py-3 rounded-lg bg-black/30 border border-purple-500/30 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
        <div>
          <label className="block text-white font-semibold mb-2">Background</label>
          <select
            value={background}
            onChange={(e) => setBackground(e.target.value)}
            className="w-full px-4 py-2 rounded-lg bg-black/30 border border-purple-500/30 text-white focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50"
          >
            {backgrounds.map(bg => (
              <option key={bg.id} value={bg.id}>{bg.label}</option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-white font-semibold mb-2">Nhạc Nền</label>
          <select
            value={musicOption}
            onChange={(e) => setMusicOption(e.target.value)}
            className="w-full px-4 py-2 rounded-lg bg-black/30 border border-purple-500/30 text-white focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50"
          >
            {musicOptions.map(music => (
              <option key={music.id} value={music.id}>{music.label}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Xem Trước Background</label>
        <div className={`h-40 rounded-lg ${backgrounds.find(bg => bg.id === background)?.color} flex items-center justify-center text-white font-semibold`}>
          Xem trước nền: {backgrounds.find(bg => bg.id === background)?.label}
        </div>
      </div>

      <div className="flex gap-4 flex-col md:flex-row">
        <button
          onClick={handleCreateVideo}
          disabled={isLoading || !title.trim() || !text.trim()}
          className="flex-1 bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-lg transition-all flex items-center justify-center gap-2"
        >
          {isLoading ? (
            <>
              <Loader size={20} className="animate-spin" />
              Đang Tạo Video...
            </>
          ) : (
            <>
              <Play size={20} />
              Tạo Video
            </>
          )}
        </button>

        <button
          disabled={!videoUrl}
          className="flex-1 bg-gradient-to-r from-green-500 to-emerald-500 hover:from-green-600 hover:to-emerald-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-lg transition-all flex items-center justify-center gap-2"
        >
          <Download size={20} />
          Tải Xuống Video
        </button>
      </div>

      <div className="mt-8 p-4 bg-blue-500/10 border border-blue-500/30 rounded-lg">
        <p className="text-blue-200 text-sm">
          <strong>ℹ️ Lưu ý:</strong> Tính năng tạo video cần backend hoặc API bên thứ 3. Vui lòng cấu hình thêm để sử dụng đầy đủ.
        </p>
      </div>
    </div>
  )
}"},{"path":"media-converter/src/pages/ImageToVideo.jsx","content":"import { useState } from 'react'
import { Upload, Loader, Download, X } from 'lucide-react'

export default function ImageToVideo() {
  const [images, setImages] = useState([])
  const [speed, setSpeed] = useState(3)
  const [musicOption, setMusicOption] = useState('none')
  const [isLoading, setIsLoading] = useState(false)

  const musicOptions = [
    { id: 'none', label: 'Không Có Nhạc' },
    { id: 'smooth', label: 'Smooth - Êm Ái' },
    { id: 'upbeat', label: 'Upbeat - Năng Động' },
    { id: 'emotional', label: 'Emotional - Cảm Động' },
  ]

  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files)
    files.forEach(file => {
      const reader = new FileReader()
      reader.onload = (event) => {
        setImages(prev => [...prev, {
          id: Date.now() + Math.random(),
          src: event.target.result,
          name: file.name
        }])
      }
      reader.readAsDataURL(file)
    })
  }

  const handleRemoveImage = (id) => {
    setImages(prev => prev.filter(img => img.id !== id))
  }

  const handleCreateVideo = async () => {
    if (images.length < 2) {
      alert('Vui lòng tải lên ít nhất 2 hình ảnh!')
      return
    }

    setIsLoading(true)
    try {
      setTimeout(() => {
        alert('Bản miễn phí cần cấu hình backend để tạo video từ ảnh. Vui lòng xem tài liệu để cấu hình thêm!')
        setIsLoading(false)
      }, 2000)
    } catch (error) {
      console.error('Lỗi:', error)
      alert('Không thể tạo video!')
      setIsLoading(false)
    }
  }

  return (
    <div className="max-w-2xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-6">🖼️ Chuyển Ảnh Thành Video</h2>

      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Tải Lên Hình Ảnh</label>
        <label className="block border-2 border-dashed border-purple-500/30 rounded-lg p-8 cursor-pointer hover:bg-purple-500/5 transition">
          <div className="flex items-center justify-center gap-2 text-gray-400">
            <Upload size={24} />
            <span>Nhấp hoặc kéo ảnh vào đây (PNG, JPG, GIF)</span>
          </div>
          <input
            type="file"
            multiple
            accept="image/*"
            onChange={handleImageUpload}
            className="hidden"
          />
        </label>
        <p className="text-gray-400 text-sm mt-2">Đã tải lên: {images.length} hình ảnh</p>
      </div>

      {images.length > 0 && (
        <div className="mb-6">
          <label className="block text-white font-semibold mb-2">Danh Sách Hình Ảnh</label>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {images.map((img, idx) => (
              <div key={img.id} className="relative group">
                <img
                  src={img.src}
                  alt={img.name}
                  className="w-full h-24 object-cover rounded-lg"
                />
                <div className="absolute top-0 left-0 right-0 bg-black/50 text-white text-xs px-2 py-1 rounded-t-lg">
                  Ảnh {idx + 1}
                </div>
                <button
                  onClick={() => handleRemoveImage(img.id)}
                  className="absolute top-1 right-1 bg-red-500 hover:bg-red-600 text-white p-1 rounded opacity-0 group-hover:opacity-100 transition"
                >
                  <X size={16} />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
        <div>
          <label className="block text-white font-semibold mb-2">Tốc Độ: {speed}s/ảnh</label>
          <input
            type="range"
            min="1"
            max="10"
            step="1"
            value={speed}
            onChange={(e) => setSpeed(parseInt(e.target.value))}
            className="w-full h-2 bg-purple-500/30 rounded-lg appearance-none cursor-pointer accent-purple-500"
          />
        </div>

        <div>
          <label className="block text-white font-semibold mb-2">Nhạc Nền</label>
          <select
            value={musicOption}
            onChange={(e) => setMusicOption(e.target.value)}
            className="w-full px-4 py-2 rounded-lg bg-black/30 border border-purple-500/30 text-white focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50"
          >
            {musicOptions.map(music => (
              <option key={music.id} value={music.id}>{music.label}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="mb-6 p-4 bg-blue-500/10 border border-blue-500/30 rounded-lg">
        <p className="text-blue-200 text-sm">
          <strong>ℹ️ Thời lượng video:</strong> {(images.length * speed).toFixed(0)} giây
        </p>
      </div>

      <div className="flex gap-4 flex-col md:flex-row">
        <button
          onClick={handleCreateVideo}
          disabled={isLoading || images.length < 2}
          className="flex-1 bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-lg transition-all flex items-center justify-center gap-2"
        >
          {isLoading ? (
            <>
              <Loader size={20} className="animate-spin" />
              Đang Tạo Video...
            </>
          ) : (
            <>
              <Download size={20} />
              Tạo Video
            </>
          )}
        </button>
      </div>
    </div>
  )
}"},{"path":"media-converter/src/pages/ScriptAnalyzer.jsx","content":"import { useState } from 'react'
import { Loader, Wand2, Download, Copy, Check } from 'lucide-react'
import { analyzeScript } from '../services/openrouter'

export default function ScriptAnalyzer() {
  const [script, setScript] = useState('')
  const [style, setStyle] = useState('chinese')
  const [isLoading, setIsLoading] = useState(false)
  const [analysis, setAnalysis] = useState('')
  const [copied, setCopied] = useState(false)

  const styles = [
    { id: 'anime', label: '🎨 Anime Nhật Bản', desc: 'Phong cách anime 2D' },
    { id: 'chinese', label: '🏯 Cổ Trang Trung Quốc', desc: 'Phong cách cổ trang Trung Quốc' },
    { id: 'watercolor', label: '🎭 Màu Nước Tây Phương', desc: 'Phong cách màu nước tây phương' },
    { id: 'manga', label: '📖 Manga Truyên Tranh', desc: 'Phong cách truyên tranh Manga' },
  ]

  const handleAnalyzeScript = async () => {
    if (!script.trim()) {
      alert('Vui lòng nhập kịch bản!')
      return
    }

    setIsLoading(true)
    try {
      const result = await analyzeScript(script, style)
      setAnalysis(result)
    } catch (error) {
      console.error('Lỗi:', error)
      alert('Không thể phân tích kịch bản. Kiểm tra API Key hoặc kết nối internet!')
    } finally {
      setIsLoading(false)
    }
  }

  const handleCopyAnalysis = () => {
    navigator.clipboard.writeText(analysis)
    setCopied(true)
    setTimeout(() => setCopied(false), 2000)
  }

  const examples = [
    {
      title: '✨ Ví dụ 1: Cô gái trên lâu đài',
      text: 'Một cô gái mặc áo cổ trang Trung Quốc đứng trên tòa lâu đài cao, nhìn ra phía dưới thung lũng. Mặt trời lặn tạo ra ánh sáng vàng rực rỡ. Trên tay cô ấy là một quyển sách cổ xưa. Cảm xúc: buồn bã, mơ mộng.'
    },
    {
      title: '⚔️ Ví dụ 2: Trận chiến anh hùng',
      text: 'Hai chiến binh cổ trang Đông Phương đối diện nhau trong một trận chiến epicc. Họ cầm kiếm sáng bạc, mặt trời mọc phía sau. Lá cây rơi xuống từ trên trời. Cảm xúc: kịch tính, mãnh liệt.'
    },
    {
      title: '🌸 Ví dụ 3: Vườn hoa trong mơ',
      text: 'Một thiếu nữ xinh đẹp đứng giữa vườn hoa anh đào nở rộ. Cô ấy mặc áo trắng bay bổng. Những cánh hoa rơi xuống như tuyết. Ánh sáng mềm mại từ mặt trời chiều. Cảm xúc: yên bình, lãng mạn.'
    }
  ]

  return (
    <div className="max-w-3xl mx-auto">
      <h2 className="text-3xl font-bold text-white mb-6">🤖 Phân Tích Kịch Bản & Vẽ Hình 2D</h2>

      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Nhập Kịch Bản</label>
        <textarea
          value={script}
          onChange={(e) => setScript(e.target.value)}
          placeholder="Nhập kịch bản hoặc tình huống bạn muốn AI vẽ thành hình ảnh..."
          className="w-full h-40 px-4 py-3 rounded-lg bg-black/30 border border-purple-500/30 text-white placeholder-gray-500 focus:outline-none focus:border-purple-500 focus:ring-2 focus:ring-purple-500/50"
        />
        <p className="text-gray-400 text-sm mt-2">{script.length} ký tự</p>
      </div>

      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">Lựa Chọn Phong Cách</label>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {styles.map(st => (
            <button
              key={st.id}
              onClick={() => setStyle(st.id)}
              className={`p-4 rounded-lg border-2 transition ${
                style === st.id
                  ? 'border-purple-500 bg-purple-500/20'
                  : 'border-purple-500/30 hover:border-purple-500/60 hover:bg-purple-500/10'
              }`}
            >
              <div className="text-white font-semibold">{st.label}</div>
              <div className="text-gray-400 text-sm">{st.desc}</div>
            </button>
          ))}
        </div>
      </div>

      <div className="mb-6">
        <label className="block text-white font-semibold mb-2">📝 Ví Dụ Kịch Bản</label>
        <div className="space-y-2">
          {examples.map((ex, idx) => (
            <button
              key={idx}
              onClick={() => setScript(ex.text)}
              className="w-full text-left px-4 py-2 bg-purple-500/10 border border-purple-500/30 rounded hover:bg-purple-500/20 text-gray-300 text-sm transition"
            >
              {ex.title}
            </button>
          ))}
        </div>
      </div>

      <div className="flex gap-4 flex-col md:flex-row mb-6">
        <button
          onClick={handleAnalyzeScript}
          disabled={isLoading || !script.trim()}
          className="flex-1 bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-3 rounded-lg transition-all flex items-center justify-center gap-2"
        >
          {isLoading ? (
            <>
              <Loader size={20} className="animate-spin" />
              Đang Phân Tích...
            </>
          ) : (
            <>
              <Wand2 size={20} />
              Phân Tích & Tạo Hình
            </>
          )}
        </button>
      </div>

      {analysis && (
        <div className="mb-6 p-4 bg-purple-500/10 border border-purple-500/30 rounded-lg">
          <div className="flex justify-between items-center mb-3">
            <h3 className="text-white font-semibold">📋 Kết Quả Phân Tích:</h3>
            <button
              onClick={handleCopyAnalysis}
              className="flex items-center gap-1 px-3 py-1 bg-purple-500/20 hover:bg-purple-500/30 text-purple-200 rounded transition"
            >
              {copied ? (
                <>
                  <Check size={16} />
                  Đã sao chép!
                </>
              ) : (
                <>
                  <Copy size={16} />
                  Sao chép
                </>
              )}
            </button>
          </div>
          <div className="text-gray-300 text-sm whitespace-pre-wrap bg-black/30 p-3 rounded border border-purple-500/20 max-h-80 overflow-y-auto">
            {analysis}
          </div>
        </div>
      )}

      <div className="p-4 bg-blue-500/10 border border-blue-500/30 rounded-lg">
        <p className="text-blue-200 text-sm mb-2">
          <strong>ℹ️ Cách sử dụng:</strong>
        </p>
        <ul className="text-blue-200 text-sm space-y-1 ml-4 list-disc">
          <li>Nhập mô tả chi tiết kịch bản bạn muốn AI vẽ</li>
          <li>Chọn phong cách hình ảnh (Cổ Trang Trung Quốc được khuyên dùng)</li>
          <li>AI sẽ phân tích và tạo mô tả chi tiết tự động</li>
          <li>Copy mô tả để dùng cho các ứng dụng vẽ AI khác (DALL-E, Midjourney, etc.)</li>
          <li>Cần cấu hình OpenRouter API Key để sử dụng đầy đủ</li>
        </ul>
      </div>
    </div>
  )
}"},{"path":"media-converter/src/services/openrouter.js","content":"import axios from 'axios'

const OPENROUTER_API_KEY = import.meta.env.VITE_OPENROUTER_API_KEY

const openrouterClient = axios.create({
  baseURL: 'https://openrouter.ai/api/v1',
  headers: {
    'Authorization': `Bearer ${OPENROUTER_API_KEY}`,
    'Content-Type': 'application/json',
  }
})

export const analyzeScript = async (script, style) => {
  if (!OPENROUTER_API_KEY) {
    throw new Error('OpenRouter API Key chưa được cấu hình. Vui lòng thêm VITE_OPENROUTER_API_KEY vào .env.local')
  }

  try {
    const styleDescriptions = {
      anime: 'anime 2D Nhật Bản với đôi mắt lớn, màu sắc sáng',
      chinese: 'cổ trang Trung Quốc với áo váy cổ điển, cảnh canh phong thủy',
      watercolor: 'màu nước tây phương với hiệu ứng mềm mại, lãng mạn',
      manga: 'truyên tranh Manga với đường nét sắc nét, cơ bắp rõ',
    }

    const prompt = `Bạn là một chuyên gia vẽ hình ảnh 2D phong cách ${styleDescriptions[style] || style}.

HÃY PHÂN TÍCH KỊCH BẢN SAU VÀ TẠO MÔ TẢ CHI TIẾT ĐỂ VẼ:

Kịch bản:
${script}

MÔ TẢ PHẢI BAO GỒM:
1. Nhân vật chính:
   - Diện mạo chi tiết (tuổi, giới tính, đặc điểm nổi bật)
   - Trang phục cụ thể (màu sắc, kiểu dáng, trang sức)
   - Biểu cảm khuôn mặt
   - Tư thế cơ thể

2. Cảnh canh:
   - Địa điểm cụ thể
   - Các vật dụng và chi tiết xung quanh
   - Thời gian của ngày (sáng, chiều, tối)
   - Ánh sáng (sáng, tối, có bóng)

3. Cảm xúc & Không khí:
