   - Cách sử dụng màu

HÃY TẠO MÔ TẢ SINH ĐỘNG, CHI TIẾT VÀ DỄ HÌNH DUNG NHẤT!`

    const response = await openrouterClient.post('/chat/completions', {
      model: 'mistral/mistral-7b-instruct:free',
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ],
      max_tokens: 2048,
      temperature: 0.7
    })

    return response.data.choices[0].message.content
  } catch (error) {
    console.error('Error analyzing script:', error)
    if (error.response?.status === 401) {
      throw new Error('API Key không hợp lệ. Vui lòng kiểm tra lại.')
    }
    throw new Error('Không thể phân tích kịch bản. Kiểm tra API Key hoặc kết nối internet!')
  }
}

export default {
  analyzeScript
}"},{"path":"media-converter/src/store/appStore.js","content":"import { create } from 'zustand'

export const useAppStore = create((set) => ({
  // State
  currentTab: 'tts',
  apiKey: localStorage.getItem('openrouter_key') || '',
  conversions: [],
  notifications: [],

  // Actions
  setCurrentTab: (tab) => set({ currentTab: tab }),

  setApiKey: (key) => {
    localStorage.setItem('openrouter_key', key)
    set({ apiKey: key })
  },

  addConversion: (conversion) => set((state) => ({
    conversions: [conversion, ...state.conversions]
  })),

  addNotification: (notification) => set((state) => ({
    notifications: [notification, ...state.notifications]
  })),

  removeNotification: (id) => set((state) => ({
    notifications: state.notifications.filter(n => n.id !== id)
  })),

  clearConversions: () => set({ conversions: [] })
}))

export default useAppStore"},{"path":"media-converter/src/utils/audioUtils.js","content":"// Utility để xử lý audio
