            >
              {copied ? (
                <>
                  <Check size={16} />
                  Đã sao chép!
                </>
              ) : (
                <>
                  <Copy size={16} />
                  Sao chép
                </>
              )}
            </button>
          </div>
          <div className="text-gray-300 text-sm whitespace-pre-wrap bg-black/30 p-3 rounded border border-purple-500/20 max-h-80 overflow-y-auto">
            {analysis}
          </div>
        </div>
      )}

      <div className="p-4 bg-blue-500/10 border border-blue-500/30 rounded-lg">
        <p className="text-blue-200 text-sm mb-2">
          <strong>ℹ️ Cách sử dụng:</strong>
        </p>
        <ul className="text-blue-200 text-sm space-y-1 ml-4 list-disc">
          <li>Nhập mô tả chi tiết kịch bản bạn muốn AI vẽ</li>
          <li>Chọn phong cách hình ảnh (Cổ Trang Trung Quốc được khuyên dùng)</li>
          <li>AI sẽ phân tích và tạo mô tả chi tiết tự động</li>
          <li>Copy mô tả để dùng cho các ứng dụng vẽ AI khác (DALL-E, Midjourney, etc.)</li>
          <li>Cần cấu hình OpenRouter API Key để sử dụng đầy đủ</li>
        </ul>
      </div>
    </div>
  )
}"},{"path":"media-converter/src/services/openrouter.js","content":"import axios from 'axios'

const OPENROUTER_API_KEY = import.meta.env.VITE_OPENROUTER_API_KEY

const openrouterClient = axios.create({
  baseURL: 'https://openrouter.ai/api/v1',
  headers: {
    'Authorization': `Bearer ${OPENROUTER_API_KEY}`,
    'Content-Type': 'application/json',
  }
})

export const analyzeScript = async (script, style) => {
  if (!OPENROUTER_API_KEY) {
    throw new Error('OpenRouter API Key chưa được cấu hình. Vui lòng thêm VITE_OPENROUTER_API_KEY vào .env.local')
  }

  try {
    const styleDescriptions = {
      anime: 'anime 2D Nhật Bản với đôi mắt lớn, màu sắc sáng',
      chinese: 'cổ trang Trung Quốc với áo váy cổ điển, cảnh canh phong thủy',
      watercolor: 'màu nước tây phương với hiệu ứng mềm mại, lãng mạn',
      manga: 'truyên tranh Manga với đường nét sắc nét, cơ bắp rõ',
    }

    const prompt = `Bạn là một chuyên gia vẽ hình ảnh 2D phong cách ${styleDescriptions[style] || style}.

HÃY PHÂN TÍCH KỊCH BẢN SAU VÀ TẠO MÔ TẢ CHI TIẾT ĐỂ VẼ:

Kịch bản:
${script}

MÔ TẢ PHẢI BAO GỒM:
1. Nhân vật chính:
   - Diện mạo chi tiết (tuổi, giới tính, đặc điểm nổi bật)
   - Trang phục cụ thể (màu sắc, kiểu dáng, trang sức)
   - Biểu cảm khuôn mặt
   - Tư thế cơ thể

2. Cảnh canh:
   - Địa điểm cụ thể
   - Các vật dụng và chi tiết xung quanh
   - Thời gian của ngày (sáng, chiều, tối)
   - Ánh sáng (sáng, tối, có bóng)

3. Cảm xúc & Không khí:
   - Tâm trạng chung
   - Tông màu chủ yếu
   - Cảm giác không gian

4. Chi tiết kỹ thuật:
   - Phong cách vẽ
   - Mức độ chi tiết
   - Cách sử dụng màu

HÃY TẠO MÔ TẢ SINH ĐỘNG, CHI TIẾT VÀ DỄ HÌNH DUNG NHẤT!`

    const response = await openrouterClient.post('/chat/completions', {
      model: 'mistral/mistral-7b-instruct:free',
      messages: [
        {
          role: 'user',
          content: prompt
        }
      ],
      max_tokens: 2048,
      temperature: 0.7
    })

    return response.data.choices[0].message.content
  } catch (error) {
    console.error('Error analyzing script:', error)
    if (error.response?.status === 401) {
      throw new Error('API Key không hợp lệ. Vui lòng kiểm tra lại.')
    }
    throw new Error('Không thể phân tích kịch bản. Kiểm tra API Key hoặc kết nối internet!')
  }
}

export default {
  analyzeScript
}"},{"path":"media-converter/src/store/appStore.js","content":"import { create } from 'zustand'

export const useAppStore = create((set) => ({
  // State
  currentTab: 'tts',
  apiKey: localStorage.getItem('openrouter_key') || '',
  conversions: [],
  notifications: [],

  // Actions
  setCurrentTab: (tab) => set({ currentTab: tab }),

  setApiKey: (key) => {
    localStorage.setItem('openrouter_key', key)
    set({ apiKey: key })
  },

  addConversion: (conversion) => set((state) => ({
    conversions: [conversion, ...state.conversions]
  })),

  addNotification: (notification) => set((state) => ({
    notifications: [notification, ...state.notifications]
  })),

  removeNotification: (id) => set((state) => ({
    notifications: state.notifications.filter(n => n.id !== id)
  })),

  clearConversions: () => set({ conversions: [] })
}))

export default useAppStore"},{"path":"media-converter/src/utils/audioUtils.js","content":"// Utility để xử lý audio
export const generateAudioFromText = (text, language = 'vi-VN', speed = 1) => {
  const utterance = new SpeechSynthesisUtterance(text)
  utterance.lang = language
  utterance.rate = speed
  utterance.pitch = 1
  utterance.volume = 1

  return utterance
}

// Utility để lấy các ngôn ngữ hỗ trợ
export const getSupportedLanguages = () => {
  return [
    { code: 'vi-VN', label: 'Tiếng Việt' },
