    { code: 'ko-KR', label: 'Tiếng Hàn' },
    { code: 'es-ES', label: 'Tiếng Tây Ban Nha' },
    { code: 'fr-FR', label: 'Tiếng Pháp' },
    { code: 'de-DE', label: 'Tiếng Đức' },
  ]
}

export default {
